# A toy memory manager. RAM has 16 blocks. '.' means a free block.
RAM_BLOCKS = 16
memory = ["."] * RAM_BLOCKS

programs = [("Browser", 5), ("Music", 2), ("Game", 7), ("Email", 3), ("Video editor", 4)]

def show():
    print("   RAM:", " ".join(memory))

def allocate(name, size):
    free = [i for i in range(RAM_BLOCKS) if memory[i] == "."]
    if len(free) < size:
        print(name, "needs", size, "blocks but only", len(free), "are free -> OUT OF MEMORY")
        return False
    for i in free[:size]:
        memory[i] = name[0]          # mark the block with the program's first letter
    print(name, "allocated", size, "blocks")
    return True

def free(name):
    for i in range(RAM_BLOCKS):
        if memory[i] == name[0]:
            memory[i] = "."
    print(name, "closed - its blocks are free again")

for name, size in programs:
    allocate(name, size)
    show()

# A tiny file system. Folders are dictionaries. Files hold their permissions.
fs = {
    "Documents": {"essay.docx": "rw", "notes.txt": "rw"},
    "Pictures":  {"holiday.jpg": "r"},
    "School":    {}
}

def show():
    for folder in fs:
        print(folder + "/")
        for f in fs[folder]:
            print("    " + f.ljust(14) + "[" + fs[folder][f] + "]")
    print()

def create(folder, name, perms="rw"):
    fs[folder][name] = perms
    print("Created", folder + "/" + name)

def move(src, dst, name):
    fs[dst][name] = fs[src].pop(name)
    print("Moved", name, "from", src, "to", dst)

def delete(folder, name):
    if "w" not in fs[folder][name]:
        print("Permission denied: cannot delete", name)
        return
    del fs[folder][name]
    print("Deleted", folder + "/" + name)

show()
create("School", "homework.py")
move("Documents", "School", "notes.txt")
delete("Pictures", "holiday.jpg")
delete("Documents", "essay.docx")
print()
show()
